Ltac prd H i RD :=
  let w := fresh "w" in let N := fresh "N" in
  lazymatch type of H with
  | u32arr ?sg ?mm ?A ?l =>
      destruct (nth_error l (Z.to_nat i)) as [w|] eqn:N; [| exfalso; apply nth_error_None in N; lia];
      pose proof (u32arr_read sg mm A l i w _ H N ltac:(lia) ltac:(f_equal; lia)) as RD; clear N
  | bytes_at ?sg ?mm ?A (u32s ?l) =>
      destruct (nth_error l (Z.to_nat i)) as [w|] eqn:N; [| exfalso; apply nth_error_None in N; lia];
      pose proof (u32ro_read sg mm A l i w _ H N ltac:(lia) ltac:(f_equal; lia)) as RD; clear N
  end.
Ltac prds i RD := first [ match goal with H : bytes_at _ _ _ (u32s _) |- _ => prd H i RD end
                        | match goal with H : u32arr _ _ _ _ |- _ => prd H i RD end ].
Ltac rds i := first [ match goal with H : bytes_at _ _ _ (u32s _) |- _ => rd H i end
                    | match goal with H : u32arr _ _ _ _ |- _ => rd H i end ].

(* [comment removed for export] *)
Ltac shadow_chk_x H xn n :=
  try unfold mkR;
  lazymatch goal with |- _ (MS ?R _ _ _ _ _ _) =>
    let v := getx R xn in
    lazymatch v with
    | Z_to_bv 64 (Z.shiftr ?c 3 + _) => shadow_chk H c n
    | Z_to_bv 64 (_ + Z.shiftr ?c 3) => shadow_chk H c n
    end
  end.
(* [comment removed for export] *)
Ltac shadow_chk_sh H c E :=
  let k := fresh "k" in let RD := fresh "RD" in let HK := fresh "HK" in
  shadow_byte H c 4 as k RD HK;
  lazymatch type of RD with
  | ov_read_bytes _ _ (Z_to_bv 64 ?a0) _ = _ =>
    replace a0 with E in RD by (rewrite ?Z.shiftr_div_pow2 by lia; change (2^3) with 8; lia)
  | bytes_at _ _ ?a0 _ =>
    replace a0 with E in RD by (rewrite ?Z.shiftr_div_pow2 by lia; change (2^3) with 8; lia)
  end;
  zstep; clear RD; step_to_if; shadow_merge c k HK.

(* [comment removed for export] *)
Ltac shadow_chk_shx H xn :=
  try unfold mkR;
  lazymatch goal with |- _ (MS ?R _ _ _ _ _ _) =>
    let v := getx R xn in
    lazymatch v with
    | Z_to_bv 64 (Z.shiftr ?b 3 + ?sb + ?kk) =>
      let k := fresh "k" in let RD := fresh "RD" in let HK := fresh "HK" in
      shadow_byte H (b + 8 * kk) 4 as k RD HK;
      lazymatch type of RD with
      | ov_read_bytes _ _ (Z_to_bv 64 ?a0) _ = _ =>
        replace a0 with (Z.shiftr b 3 + sb + kk) in RD by (rewrite ?Z.shiftr_div_pow2 by lia; change (2^3) with 8; lia)
      | bytes_at _ _ ?a0 _ =>
        replace a0 with (Z.shiftr b 3 + sb + kk) in RD by (rewrite ?Z.shiftr_div_pow2 by lia; change (2^3) with 8; lia)
      end;
      zstep; clear RD; step_to_if; shadow_merge (b + 8 * kk) k HK
    end
  end.

Ltac ml_shape T :=
  lazymatch T with
  | Z.le _ _ => idtac | Z.lt _ _ => idtac | @eq Z _ _ => idtac | @eq nat _ _ => idtac
  | ?A /\ ?B => ml_shape A; ml_shape B
  end.
Lemma ml_land3 : forall x, Z.land x 3 = x mod 4.
Proof. intros x. change 3 with (Z.ones 2). rewrite Z.land_ones by lia. reflexivity. Qed.
Ltac ml_lia_core :=
  repeat match goal with H : ?T |- _ =>
    lazymatch type of T with Prop => tryif ml_shape T then fail else clear H end end;
  rewrite ?land_7_mod', ?ml_land3 in *; rewrite ?Z.shiftr_div_pow2 in * by lia; try change (2 ^ 3) with 8 in *; lia.
Ltac ml_lia :=
  first [ repeat match goal with
                 | H : context [zlow _ _] |- _ => clear H | H : context [Z.b2z _] |- _ => clear H
                 | H : context [lval _ _] |- _ => clear H | H : context [w32 _] |- _ => clear H
                 end; ml_lia_core
        | ml_lia_core ].
Ltac ml_side :=
  first [ reflexivity | assumption
        | lazymatch goal with
          | |- @eq (bv _) _ _ => f_equal; first [xlia0 | ml_lia]
          | |- _ => first [xlia0 | ml_lia]
          end ].

Section Walk.
  Variable AL : asan_layout.
  Hypothesis IMG : asan_img_ok AL.
  Hypothesis ALWF : al_wf AL.
  Local Instance lxi : LxImg asegs AL := lxA_img AL IMG.
  Variable CS : Z -> Prop.
  Hypothesis CSOK : cs_ok AL CS.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem)
            (D dl S sl slm ld ls lo : Z) (ds0 ss : list word).
  Hypothesis Hdl : 0 <= dl <= 10000.
  Hypothesis Hsl : 0 <= sl <= 10000.
  Hypothesis Hslm : 0 <= slm /\ slm <= dl /\ slm <= sl.
  Hypothesis Ln : dl <= ld /\ sl <= ls.
  Hypothesis L0 : Z.of_nat (length ds0) = ld.
  Hypothesis LS : Z.of_nat (length ss) = ls.
  Hypothesis DB : 0 < D /\ D + 4 * ld <= 2^64.
  Hypothesis SB0 : 0 <= S /\ S + 4 * ls <= 2^64.
  Hypothesis DTOP : D + 4 * ld < 2^64.
  Hypothesis STOP : S + 4 * ls < 2^64.
  Hypothesis NZS : sl = 0 \/ 0 < S.
  Hypothesis SPR : 0 <= bv_unsigned sp < 2^64.
  Hypothesis LO0 : 0 <= lo.
  Hypothesis LO : lo <= bv_unsigned sp - 112.
  Hypothesis SCS : crange CS lo (bv_unsigned sp - lo).
  Hypothesis SX : D + 4 * ld <= bv_unsigned sp - 112 \/ bv_unsigned sp <= D.
  Hypothesis SSX : S + 4 * ls <= bv_unsigned sp - 112 \/ bv_unsigned sp <= S.
  Hypothesis RA : bv_unsigned ra mod 2 = 0.
  Hypothesis ALD : D mod 4 = 0.
  Hypothesis ALS : S mod 4 = 0.
  Hypothesis SLMIN : slm = Z.min dl sl.

  Notation POST := (mpi_core_mla_postA asegs ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc D dl ds0 lo m).
  Notation W := [(D, D + 4 * dl); (bv_unsigned sp - 112, bv_unsigned sp)].
  Notation SP' := (Z_to_bv 64 (bv_unsigned sp + -112)).
  Notation SB := (Z_to_bv 64 (al_sb AL)).
  Notation FRAME mm c := (rw_cells asegs mm (bv_unsigned sp + -112) [c; C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]).
  Notation SFACT mm := ((S = D /\ ss = ds0) \/ (bytes_at asegs mm S (u32s ss) /\ (S + 4 * ls <= D \/ D + 4 * ld <= S))).
  Notation DINV mm ds := (u32arr asegs mm D ds /\ Z.of_nat (length ds) = ld
                          /\ munch W m mm /\ wmono asegs m mm /\ mem_inv asegs mm /\ stk asegs mm lo (bv_unsigned sp + -112)).
  Notation AOBJ mm := (aobj asegs AL CS mm D (4 * dl) /\ aobj asegs AL CS mm S (4 * slm)).

  (* [comment removed for export] *)
  Ltac mla_ret EI LXh SFh :=
    lx_post;
    [> eassumption
     | rewrite ?upd_length; xlia LXh L0
     | apply same_from_skipn; [rewrite <- EI; exact SFh | rewrite ?upd_length; xlia LXh L0]
     | .. ].

  Lemma frame_C8_CB : forall mm w, FRAME mm (C8 w) -> FRAME mm (CB 8 (le8 w)).
  Proof.
    intros mm w [[WF HB] WR]. split; [split|]; [ split; [apply length_le8 | exact (proj2 WF)] | exact HB | exact WR ].
  Qed.

  (* [comment removed for export] *)
  Lemma excess_walk : forall (k : nat) (i ex en : Z) (ds : list word) (mm : mem) (jk : list byte)
      (xra xt0 xt2 xs1 xa3 xa5 wc xa7 xs2 xs3 xs4 xs5 xs6 xs7 xs8 xs9 xs10 xs11 xt3 xt4 xt5 xt6 wa2 wa4 : word),
    Z.to_nat (dl - i) = k -> slm <= i < dl -> ex = D + 4 * i -> en = i - dl ->
    wa2 = Z_to_bv 64 (-5) -> wa4 = Z_to_bv 64 0 ->
    DINV mm ds -> AOBJ mm -> FRAME mm (CB 8 jk) -> same_from (Z.to_nat i) ds ds0 ->
    evtA asegs AL CS POST
      (MS (mkR xra SP' gp tp xt0 SB xt2 (Z_to_bv 64 ex) xs1 (Z_to_bv 64 ex) (Z_to_bv 64 en) wa2 xa3 wa4 xa5 wc xa7
               xs2 xs3 xs4 xs5 xs6 xs7 xs8 xs9 xs10 xs11 xt3 xt4 xt5 xt6)
          F (Z_to_bv 64 0xa515c) fc None mm (seg_rom asegs)).
  (* [comment removed for export] *)
  Proof.
    induction k as [|k IH]; intros i ex en ds mm jk xra xt0 xt2 xs1 xa3 xa5 wc xa7 xs2 xs3 xs4 xs5 xs6 xs7 xs8 xs9 xs10 xs11 xt3 xt4 xt5 xt6 wa2 wa4
      Hk Hi Ex En -> -> (HX & LX0 & MU & WM & MI & ST) [OD OS] FR FS; [exfalso; xlia Hk Hi|].
    pose proof (cs_ok_sb _ _ CSOK) as SB64.
    lx_limb_rw HX i Ex ltac:(xlia Hi Hslm) ltac:(xlia Hi Hslm Ln LX0) dx NX.
    lx_hide HX. lx_hide MU. lx_hide WM.
    lx_run_tac (PLAN [0xa515c] [(0xa5170, DJoin)] 60%N); lx_tree.
    all: lx_unhide; lx_gc.
    all: lx_rn_rw ex CX'; lx_rn_munch MUl; lx_rn_wmono WMl; lx_rn_mi MI'; lx_rn_stk ST'.
    all: pose proof (u32arr_upd_of_cell _ _ _ _ _ _ _ _ HX NX ltac:(xlia Hi Hslm) Ex MUl WMl CX') as HX';
         pose proof (munch_local1 _ _ _ _ _ _ _ _ _ eq_refl MU MUl ltac:(xlia Ex Hi Hslm) ltac:(xlia Ex Hi)) as MU';
         pose proof (wmono_trans _ _ _ _ WM WMl) as WM'.
    all: lazymatch type of HX' with u32arr _ _ _ (upd _ _ ?v) =>
           pose proof (same_from_upd_Zn _ _ i (i + 1) v FS ltac:(xlia Hi Hslm) eq_refl) as FS';
           assert (LX' : Z.of_nat (length (upd ds (Z.to_nat i) v)) = ld) by (rewrite upd_length; exact LX0) end.
    all: lazymatch goal with
         | |- evtA _ _ _ _ (MS _ _ (Z_to_bv 64 0xa515c) _ _ _ _) =>
             (* [comment removed for export] *)
             lx_rn_aobj D OD'; lx_rn_aobj S OS'; lx_rn_rw (bv_unsigned sp + -112) FR';
             eapply (IH (i + 1));
             first [ exact (conj HX' (conj LX' (conj MU' (conj WM' (conj MI' ST'))))) | exact (conj OD' OS') | exact FR' | exact FS'
                   | ml_side ]
         | |- _ =>
             (* [comment removed for export] *)
             assert (EI : i + 1 = dl) by ml_lia;
             mla_ret EI LX0 FS'
         end.
    all: match goal with |- ?g => idtac "EX-LEFT:" g end.
  Qed.

  (* [comment removed for export] *)
  Lemma x1_walk : forall (k : nat) (i es ed e7 : Z) (ds : list word) (mm : mem) (jk : list byte)
      (xra xt0 xs0 xs1 wc xs2 xs3 xs4 xs5 xs6 xs7 xs8 xs9 xs10 xs11 wt3 wt4 wt5 wt6 : word),
    Z.to_nat (slm - i) = k -> 0 <= i < slm -> es = S + 4 * i -> ed = D + 4 * i -> e7 = slm - i ->
    wt3 = Z_to_bv 64 0 -> wt4 = Z_to_bv 64 0 -> wt5 = Z_to_bv 64 5 -> wt6 = Z_to_bv 64 (-5) ->
    DINV mm ds -> SFACT mm -> AOBJ mm -> FRAME mm (CB 8 jk) -> same_from (Z.to_nat i) ds ds0 ->
    evtA asegs AL CS POST
      (MS (mkR xra SP' gp tp xt0 SB (Z_to_bv 64 slm) xs0 xs1 (Z_to_bv 64 ed) (Z_to_bv 64 dl) (Z_to_bv 64 es) (Z_to_bv 64 sl)
               (Z_to_bv 64 ed) (Z_to_bv 64 es) wc (Z_to_bv 64 e7)
               xs2 xs3 xs4 xs5 xs6 xs7 xs8 xs9 xs10 xs11 wt3 wt4 wt5 wt6)
          F (Z_to_bv 64 0xa5088) fc None mm (seg_rom asegs)).
  (* [comment removed for export] *)
  Proof.
    induction k as [|k IH]; intros i es ed e7 ds mm jk xra xt0 xs0 xs1 wc xs2 xs3 xs4 xs5 xs6 xs7 xs8 xs9 xs10 xs11 wt3 wt4 wt5 wt6
      Hk Hi Es Ed E7 -> -> -> -> (HX & LX0 & MU & WM & MI & ST) AS [OD OS] FR FS; [exfalso; xlia Hk Hi|].
    pose proof (cs_ok_sb _ _ CSOK) as SB64.
    assert (SPOS : 0 < S) by (clear - NZS Hi Hslm; lia).
    destruct (lx_sview mm D S ld ls i ds ds0 ss HX LX0 L0 FS LS ltac:(xlia Hi) AS) as (sv & HSV & LSV & AS3 & VSV & RSV). clear AS VSV.
    lx_limb_rw HX i Ed ltac:(xlia Hi) ltac:(xlia Hi Hslm Ln LX0) dx NX.
    pose proof (u32ro_cellq mm S sv i es HSV ltac:(xlia Hi) ltac:(xlia Hi Hslm Ln LSV) Es) as CSx.
    remember (nth (Z.to_nat i) sv w0) as vx eqn:Hvx in CSx. clear Hvx.
    lx_hide HX. lx_hide HSV. lx_hide MU. lx_hide WM.
    lx_run_tac (PLAN [0xa5088; 0xa515c] [(0xa50b0, DJoin); (0xa50c4, DJoin)] 100%N); lx_tree.
    all: lx_unhide; lx_gc.
    all: lx_rn_rw ed CX'; lx_rn_munch MUl; lx_rn_wmono WMl; lx_rn_mi MI'; lx_rn_stk ST'.
    all: pose proof (u32arr_upd_of_cell _ _ _ _ _ _ _ _ HX NX ltac:(xlia Hi) Ed MUl WMl CX') as HX';
         pose proof (RSV lxm _ _ MUl ltac:(xlia Hi Ed) ltac:(xlia Hi Ed Hslm Ln)) as AS';
         pose proof (munch_local1 _ _ _ _ _ _ _ _ _ eq_refl MU MUl ltac:(xlia Ed Hi) ltac:(xlia Ed Hi Hslm)) as MU';
         pose proof (wmono_trans _ _ _ _ WM WMl) as WM'.
    all: lazymatch type of HX' with u32arr _ _ _ (upd _ _ ?v) =>
           pose proof (same_from_upd_Zn _ _ i (i + 1) v FS ltac:(xlia Hi) eq_refl) as FS';
           assert (LX' : Z.of_nat (length (upd ds (Z.to_nat i) v)) = ld) by (rewrite upd_length; exact LX0) end.
    all: lazymatch goal with
         | |- evtA _ _ _ _ (MS _ _ (Z_to_bv 64 0xa5088) _ _ _ _) =>
             (* [comment removed for export] *)
             lx_rn_aobj D OD'; lx_rn_aobj S OS'; lx_rn_rw (bv_unsigned sp + -112) FR';
             eapply (IH (i + 1));
             first [ exact (conj HX' (conj LX' (conj MU' (conj WM' (conj MI' ST'))))) | exact AS' | exact (conj OD' OS') | exact FR'
                   | exact FS' | ml_side ]
         | |- evtA _ _ _ _ (MS _ _ (Z_to_bv 64 0xa515c) _ _ _ _) =>
             (* [comment removed for export] *)
             lx_rn_aobj D OD'; lx_rn_aobj S OS'; lx_rn_rw (bv_unsigned sp + -112) FR';
             assert (EI : i + 1 = slm) by ml_lia;
             eapply (excess_walk (Z.to_nat (dl - slm)) slm);
             first [ exact (conj HX' (conj LX' (conj MU' (conj WM' (conj MI' ST'))))) | exact (conj OD' OS') | exact FR'
                   | rewrite <- EI; exact FS' | ml_side ]
         | |- _ =>
             (* [comment removed for export] *)
             assert (EI : i + 1 = dl) by ml_lia;
             mla_ret EI LX0 FS'
         end.
    all: match goal with |- ?g => idtac "X1-LEFT:" g end.
  Qed.

  (* [comment removed for export] *)
  Lemma x8_walk : forall (k : nat) (j n8 i e2 : Z) (ds : list word) (mm : mem)
      (xra xt0 wc xa4 xa5 xa7 xs6 xs7 xs8 xs9 xs10 xs11 xt3 xt6 wb wt4 ws0 ws1 ws2 ws3 ws4 ws5 : word),
    Z.to_nat (n8 - j) = k -> 0 <= j < n8 -> 8 * n8 <= slm -> slm - 8 * n8 = slm mod 8 -> i = 8 * j -> e2 = n8 - j ->
    wt4 = Z_to_bv 64 (32 * j) -> ws0 = Z_to_bv 64 0 -> ws1 = Z_to_bv 64 0 -> ws2 = Z_to_bv 64 4 ->
    ws3 = Z_to_bv 64 (Z.shiftr D 3 + al_sb AL + 4 * j) -> ws4 = Z_to_bv 64 (Z.shiftr S 3 + al_sb AL + 4 * j) ->
    ws5 = Z_to_bv 64 (-5) ->
    DINV mm ds -> SFACT mm -> AOBJ mm -> FRAME mm (C8 wb) -> same_from (Z.to_nat i) ds ds0 ->
    evtA asegs AL CS POST
      (MS (mkR xra SP' gp tp xt0 SB (Z_to_bv 64 slm) ws0 ws1 (Z_to_bv 64 D) (Z_to_bv 64 dl) (Z_to_bv 64 S) (Z_to_bv 64 sl)
               xa4 xa5 wc xa7 ws2 ws3 ws4 ws5 xs6 xs7 xs8 xs9 xs10 xs11 xt3 wt4 (Z_to_bv 64 e2) xt6)
          F (Z_to_bv 64 0xa4b80) fc None mm (seg_rom asegs)).
  (* [comment removed for export] *)
  Proof.
    induction k as [|k IH]; intros j n8 i e2 ds mm xra xt0 wc xa4 xa5 xa7 xs6 xs7 xs8 xs9 xs10 xs11 xt3 xt6 wb wt4 ws0 ws1 ws2 ws3 ws4 ws5
      Hk Hj Hn8 Hr Hi E2 -> -> -> -> -> -> -> (HX & LX & MU & WM & MI & ST) AS [OD OS] FR FS; [exfalso; xlia Hk Hj|].
    pose proof (cs_ok_sb _ _ CSOK) as SB64.
    assert (SPOS : 0 < S) by (clear - NZS Hj Hn8 Hslm; lia).
    (* [comment removed for export] *)
    destruct (lx_sview mm D S ld ls i ds ds0 ss HX LX L0 FS LS ltac:(xlia Hj Hi) AS) as (sv & HSV & LSV & AS3 & VSV & RSV). clear AS VSV.
    pose proof (u32rw_cells8 mm D ds i (D + 32 * j) HX ltac:(xlia Hj Hi) ltac:(xlia Hj Hi Hn8 Hslm Ln LX) ltac:(xlia Hi)) as CD.
    remember (nth (Z.to_nat i) ds w0) as d0 eqn:Hd0 in CD. remember (nth (Z.to_nat (i + 1)) ds w0) as d1 eqn:Hd1 in CD.
    remember (nth (Z.to_nat (i + 2)) ds w0) as d2 eqn:Hd2 in CD. remember (nth (Z.to_nat (i + 3)) ds w0) as d3 eqn:Hd3 in CD.
    remember (nth (Z.to_nat (i + 4)) ds w0) as d4 eqn:Hd4 in CD. remember (nth (Z.to_nat (i + 5)) ds w0) as d5 eqn:Hd5 in CD.
    remember (nth (Z.to_nat (i + 6)) ds w0) as d6 eqn:Hd6 in CD. remember (nth (Z.to_nat (i + 7)) ds w0) as d7 eqn:Hd7 in CD.
    clear Hd0 Hd1 Hd2 Hd3 Hd4 Hd5 Hd6 Hd7.
    let sc q e v CSq := (pose proof (u32ro_cellq mm S sv q e HSV ltac:(xlia Hj Hi) ltac:(xlia Hj Hi Hn8 Hslm Ln LSV) ltac:(xlia Hi)) as CSq;
                        let Hv := fresh "Hv" in remember (nth (Z.to_nat q) sv w0) as v eqn:Hv in CSq; clear Hv) in
    sc i (S + 32 * j) v0 CS0; sc (i + 1) (S + 32 * j + 4) v1 CS1; sc (i + 2) (S + 32 * j + 8) v2 CS2; sc (i + 3) (S + 32 * j + 12) v3 CS3;
    sc (i + 4) (S + 32 * j + 16) v4 CS4; sc (i + 5) (S + 32 * j + 20) v5 CS5; sc (i + 6) (S + 32 * j + 24) v6 CS6; sc (i + 7) (S + 32 * j + 28) v7 CS7.
    lx_hide HX. lx_hide HSV. lx_hide MU. lx_hide WM.
    lx_run_tac (PLAN [0xa4b80; 0xa5088; 0xa515c]
      [(0xa4ba4, DJoin); (0xa4bb0, DJoin); (0xa4bc0, DJoin); (0xa4be4, DJoin); (0xa4bfc, DJoin); (0xa4c0c, DJoin); (0xa4c4c, DJoin);
       (0xa4c64, DJoin); (0xa4c78, DJoin); (0xa4cb8, DJoin); (0xa4cd0, DJoin); (0xa4ce4, DJoin); (0xa4d24, DJoin); (0xa4d3c, DJoin);
       (0xa4d50, DJoin); (0xa4d90, DJoin); (0xa4da8, DJoin); (0xa4dbc, DJoin); (0xa4dfc, DJoin); (0xa4e14, DJoin); (0xa4e28, DJoin);
       (0xa4e70, DJoin); (0xa4e88, DJoin)] 450%N); lx_tree.
    all: lx_unhide; lx_gc.
    (* [comment removed for export] *)
    all: lx_rn_rw (D + 32 * j) CD'; lx_rn_munch MUl; lx_rn_wmono WMl; lx_rn_mi MI'; lx_rn_stk ST'; lx_rn_aobj D OD'; lx_rn_aobj S OS';
         try lx_rn_rw (bv_unsigned sp + -112) FR'.
    all: pose proof (u32arr_upd8_of_cells mm lxm D ds i (D + 32 * j) _ _ _ _ _ _ _ _ _ HX ltac:(xlia Hj Hi) ltac:(xlia Hj Hi Hn8 Hslm Ln LX) ltac:(xlia Hi) MUl ltac:(xlia0) WMl CD') as HX';
         pose proof (RSV lxm _ _ MUl ltac:(xlia Hj) ltac:(xlia Hj Hn8 Hslm Ln)) as AS';
         pose proof (munch_local1 _ _ _ _ _ _ _ _ _ eq_refl MU MUl ltac:(xlia Hj) ltac:(xlia Hj Hn8 Hslm Ln)) as MU';
         pose proof (wmono_trans _ _ _ _ WM WMl) as WM'.
    all: lazymatch type of HX' with u32arr _ _ _ ?ds8 =>
           assert (SF : same_from (Z.to_nat (i + 8)) ds8 ds0) by (apply same_from_upd8_Z; [exact FS | xlia Hj Hi | xlia0]);
           assert (LX' : Z.of_nat (length ds8) = ld) by (rewrite !upd_length; exact LX) end.
    all: lazymatch goal with |- evtA _ _ _ _ (MS _ _ ?pcw _ _ _ _) =>
      lazymatch pcw with
      | Z_to_bv 64 0xa4b80 =>
         (* [comment removed for export] *)
         eapply (IH (j + 1) n8 (i + 8));
         first [ exact (conj HX' (conj LX' (conj MU' (conj WM' (conj MI' ST'))))) | exact AS' | exact (conj OD' OS') | exact FR'
               | exact SF | ml_side ]
      | Z_to_bv 64 0xa5088 =>
         (* [comment removed for export] *)
         assert (EN : i + 8 = 8 * n8) by ml_lia;
         eapply (x1_walk (Z.to_nat (slm - (i + 8))) (i + 8));
         first [ exact (conj HX' (conj LX' (conj MU' (conj WM' (conj MI' ST'))))) | exact AS' | exact (conj OD' OS')
               | exact (frame_C8_CB _ _ FR') | exact SF | ml_side ]
      | Z_to_bv 64 0xa515c =>
         (* [comment removed for export] *)
         assert (EI : i + 8 = slm) by ml_lia;
         eapply (excess_walk (Z.to_nat (dl - slm)) slm);
         first [ exact (conj HX' (conj LX' (conj MU' (conj WM' (conj MI' ST'))))) | exact (conj OD' OS')
               | exact (frame_C8_CB _ _ FR') | rewrite <- EI; exact SF | ml_side ]
      | ret_pc _ =>
         (* [comment removed for export] *)
         assert (EI : i + 8 = dl) by ml_lia;
         mla_ret EI LX SF
      end end.
    all: match goal with |- ?g => idtac "X8-LEFT:" g end.
  Qed.
End Walk.

Section Body.
  Variable AL : asan_layout.
  Hypothesis IMG : asan_img_ok AL.
  Hypothesis ALWF : al_wf AL.
  Local Instance lxiB : LxImg asegs AL := lxA_img AL IMG.
  Variable CS : Z -> Prop.
  Hypothesis CSOK : cs_ok AL CS.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem)
            (D dl S sl ld ls lo : Z) (ds0 ss : list word).
  Hypothesis Hdl : 0 <= dl <= 10000.
  Hypothesis Hsl : 0 <= sl <= 10000.
  Hypothesis Ln : dl <= ld /\ sl <= ls.
  Hypothesis L0 : Z.of_nat (length ds0) = ld.
  Hypothesis LS : Z.of_nat (length ss) = ls.
  Hypothesis DB : 0 < D /\ D + 4 * ld <= 2^64.
  Hypothesis SB0 : 0 <= S /\ S + 4 * ls <= 2^64.
  Hypothesis DTOP : D + 4 * ld < 2^64.
  Hypothesis STOP : S + 4 * ls < 2^64.
  Hypothesis NZS : sl = 0 \/ 0 < S.
  Hypothesis SPR : 0 <= bv_unsigned sp < 2^64.
  Hypothesis LO0 : 0 <= lo.
  Hypothesis LO : lo <= bv_unsigned sp - 112.
  Hypothesis SCS : crange CS lo (bv_unsigned sp - lo).
  Hypothesis SX : D + 4 * ld <= bv_unsigned sp - 112 \/ bv_unsigned sp <= D.
  Hypothesis SSX : S + 4 * ls <= bv_unsigned sp - 112 \/ bv_unsigned sp <= S.
  Hypothesis RA : bv_unsigned ra mod 2 = 0.
  Hypothesis ALD : D mod 4 = 0.
  Hypothesis ALS : S mod 4 = 0.
  Hypothesis DLT : D < 2^64.
  Hypothesis SLT : S < 2^64.

  (* [comment removed for export] *)
  Lemma body_walk : forall (xt0 xt1 xt2 xa5 xa6 xa7 xt3 xt4 xt5 xt6 xb : word),
    u32arr asegs m D ds0 ->
    ((S = D /\ ss = ds0) \/ (bytes_at asegs m S (u32s ss) /\ (S + 4 * ls <= D \/ D + 4 * ld <= S))) ->
    mem_inv asegs m -> stk asegs m lo (bv_unsigned sp) -> abase asegs AL m ->
    aobj asegs AL CS m D (4 * dl) -> aobj asegs AL CS m S (4 * Z.min dl sl) ->
    evtA asegs AL CS (mpi_core_mla_postA asegs ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc D dl ds0 lo m)
      (MS (mkR ra sp gp tp xt0 xt1 xt2 s0 s1 (Z_to_bv 64 D) (Z_to_bv 64 dl) (Z_to_bv 64 S) (Z_to_bv 64 sl) xb xa5 xa6 xa7
               s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 xt3 xt4 xt5 xt6)
          F (Z_to_bv 64 0xa4af4) fc None m (seg_rom asegs)).
  (* [comment removed for export] *)
  Proof.
    intros until xb. intros HX AS MI ST ABS OD OS.
    pose proof (cs_ok_sb _ _ CSOK) as SB64.
    pose proof (munch_refl [(D, D + 4 * dl); (bv_unsigned sp - 112, bv_unsigned sp)] m) as MU.
    pose proof (wmono_refl asegs m) as WM.
    carve_frame 112%nat ST.
    lx_run_tac (PLAN [0xa4b80; 0xa5088; 0xa515c] [] 120%N); lx_tree.
    all: lx_gc.
    (* [comment removed for export] *)
    all: lx_rn_munch MU'; lx_rn_wmono WM'; lx_rn_mi MI'; lx_rn_stk ST'; lx_rn_aobj D OD'; lx_rn_aobj S OS'; try lx_rn_rw (bv_unsigned sp + -112) FR'.
    all: match goal with K : u8arr _ _ _ _ |- _ => fail | K : u32arr _ ?mx D _ |- evtA _ _ _ _ (MS _ _ _ _ _ ?mx' _) => constr_eq mx mx'; rename K into HX' end.
    all: assert (AS' : (S = D /\ ss = ds0) \/ (bytes_at asegs lxm S (u32s ss) /\ (S + 4 * ls <= D \/ D + 4 * ld <= S)))
      by (destruct AS as [[ES ESS]|[HS DIS]]; [left; split; [exact ES| exact ESS] | right; split; [| exact DIS]];
          eapply (u32ro_transport _ _ _ _ _ _ HS MU'); cbn [disjoint_from]; rewrite LS; xlia DIS SSX Ln Hdl).
    all: lazymatch goal with |- evtA _ _ _ _ (MS (mkR _ _ _ _ _ _ (Z_to_bv 64 ?v) _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _) _ ?pcw _ _ _ _) =>
      (* [comment removed for export] *)
      assert (SLM : v = Z.min dl sl) by (match goal with K : 0 <= _ |- _ => clear - K Hdl Hsl; lia end);
      assert (Hslm : 0 <= v /\ v <= dl /\ v <= sl) by xlia SLM Hdl Hsl;
      replace (4 * Z.min dl sl) with (4 * v) in OS' by xlia SLM;
      lazymatch pcw with
      | Z_to_bv 64 0xa4b80 =>
          eapply (x8_walk AL IMG ALWF CS CSOK ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m D dl S sl v ld ls lo ds0 ss)
            with (k := Z.to_nat (v / 8)) (j := 0) (n8 := v / 8) (i := 0);
            first [ exact Hdl | exact Hsl | exact Hslm | exact Ln | exact L0 | exact LS | exact DB | exact SB0 | exact DTOP | exact STOP
                  | exact NZS | exact SPR | exact LO0 | exact LO | exact SCS | exact SX | exact SSX | exact RA | exact ALD | exact ALS | exact SLM
                  | exact (conj HX' (conj L0 (conj MU' (conj WM' (conj MI' ST')))))
                  | exact AS' | exact FR' | exact (conj OD' OS')
                  | exact (same_from_refl _ _)
                  | ml_side ]
      | Z_to_bv 64 0xa5088 =>
          eapply (x1_walk AL IMG ALWF CS CSOK ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m D dl S sl v ld ls lo ds0 ss)
            with (k := Z.to_nat v) (i := 0);
            first [ exact Hdl | exact Hsl | exact Hslm | exact Ln | exact L0 | exact LS | exact DB | exact SB0 | exact DTOP | exact STOP
                  | exact NZS | exact SPR | exact LO0 | exact LO | exact SCS | exact SX | exact SSX | exact RA | exact ALD | exact ALS | exact SLM
                  | exact (conj HX' (conj L0 (conj MU' (conj WM' (conj MI' ST')))))
                  | exact AS' | exact FR' | exact (conj OD' OS')
                  | exact (same_from_refl _ _)
                  | ml_side ]
      | Z_to_bv 64 0xa515c =>
          assert (V0 : v = 0) by ml_lia;
          eapply (excess_walk AL IMG ALWF CS CSOK ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m D dl S sl v ld ls lo ds0 ss)
            with (k := Z.to_nat (dl - v)) (i := v);
            first [ exact Hdl | exact Hsl | exact Hslm | exact Ln | exact L0 | exact LS | exact DB | exact SB0 | exact DTOP | exact STOP
                  | exact NZS | exact SPR | exact LO0 | exact LO | exact SCS | exact SX | exact SSX | exact RA | exact ALD | exact ALS | exact SLM
                  | exact (conj HX' (conj L0 (conj MU' (conj WM' (conj MI' ST')))))
                  | exact FR' | exact (conj OD' OS')
                  | rewrite V0; exact (same_from_refl _ _)
                  | ml_side ]
      | ret_pc _ =>
          apply evtA_done; unfold mpi_core_mla_postA; do 15 eexists; exists lxm, ds0;
          split; [reflexivity|]; split; [exact MU'|]; split; [exact WM'|]; split; [exact MI'|]; split; [exact HX'|]; split; [reflexivity|];
          split; [reflexivity| exact ST']
      end end.
    all: match goal with |- ?g => idtac "BODY-LEFT:" g end.
  Qed.
End Body.

Lemma A_mpi_core_mla_spec : forall AL, asan_img_ok AL -> mpi_core_mla_stmtA asegs AL A_MPI_CORE_MLA.
Proof.
  intros AL IMG. unfold mpi_core_mla_stmtA, A_MPI_CORE_MLA.
  intros until ss. intros HX HS Hdl Hsl LX LS DA ALD ALS NZD NZS DTOP STOP ST LO SPA SX SSX MI RA ALWF CSOK ABS OD OS SCS -> -> -> ->.
  unfold MPI_CORE_MLA_STACK_A in *.
  pose proof (u32arr_bound _ _ _ _ HX) as DB. pose proof (u32ro_bound _ _ _ _ HS) as SB0.
  pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR.
  pose proof (proj1 ST) as LO0.
  assert (AS : (S = D /\ ss = ds) \/ (bytes_at asegs m S (u32s ss) /\ (S + 4 * Z.of_nat (length ss) <= D \/ D + 4 * Z.of_nat (length ds) <= S))).
  { destruct DA as [[ES EQ]|DIS]; [left; split; [exact ES| exact EQ] | right; split; [exact HS | exact DIS]]. }
  eapply body_walk; try eassumption; try reflexivity; try lia.
Qed.
